; Clear the play area
; $8720-$8742

; Turns off all sprites and fills the rows 0-21 with spaces in the colour $05. On exit, $03 is 22.
clear_play_area
        lda #$00
        sta cursor_row
        sta SPENA
        lda #$20
        sta cursor_char
clear_play_area_row
        lda #$00
        sta cursor_col
clear_play_area_column
        jsr put_char
        inc cursor_col
        lda cursor_col
        cmp #$28
        bne clear_play_area_column
        inc cursor_row
        lda cursor_row
        cmp #$16
        bne clear_play_area_row
        rts
